          "code": "import numpy as np\nrng = np.random.default_rng(0)\nX = rng.normal(size=(16, 4)); y = rng.integers(0, 3, 16)\nY = np.eye(3)[y]                                        # one-hot targets\nW1, b1 = rng.normal(0,.5,(4,8)), np.zeros(8)\nW2, b2 = rng.normal(0,.5,(8,3)), np.zeros(3)\n\ndef forward(X):\n    z1 = X @ W1 + b1; a1 = np.tanh(z1)                  # cache z1, a1\n    z2 = a1 @ W2 + b2\n    p  = np.exp(z2 - z2.max(1, keepdims=True))\n    p /= p.sum(1, keepdims=True)                        # softmax\n    return z1, a1, z2, p\n\nz1, a1, z2, p = forward(X)\nloss = -np.mean(np.sum(Y*np.log(p+1e-9), axis=1))\n\n# BACKWARD (the four equations)\ndelta2 = (p - Y) / len(X)                               # softmax+CE: delta^L = p - y\ndW2 = a1.T @ delta2;  db2 = delta2.sum(0)              # weight grad = delta outer input\ndelta1 = (delta2 @ W2.T) * (1 - a1**2)                  # push back x tanh'(z) = 1 - a1^2\ndW1 = X.T @ delta1;   db1 = delta1.sum(0)\n\n# gradient check on one weight (numerical vs analytic)\ne = 1e-5; W2[0,0] += e; l1 = -np.mean(np.sum(Y*np.log(forward(X)[3]+1e-9),1)); W2[0,0] -= 2*e\nl2 = -np.mean(np.sum(Y*np.log(forward(X)[3]+1e-9),1)); W2[0,0] += e\nprint('numeric', round((l1-l2)/(2*e),8), 'vs analytic', round(dW2[0,0],8))",
